pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 initVal, uint256 lockTime, uint256 collectAm, bool callSetMinSum) public {
        // Restrict inputs to avoid revert in Collect and avoid overflow
        vm.assume(collectAm <= type(uint256).max / 2);
        vm.assume(lockTime <= type(uint256).max - block.timestamp);
        vm.assume(initVal <= type(uint256).max / 2);

        // If we call SetMinSum, set it; otherwise leave it at default 0
        if (callSetMinSum) {
            c.SetMinSum(initVal);
        }
        c.Initialized();

        // Fund the contract so Collect can work
        vm.deal(address(c), 1 ether);

        // Make a call to Put to create a Holder entry for this contract (caller is the test contract)
        c.Put{value: 0.5 ether}(lockTime);

        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);

        // Now call Collect
        (bool collectReverted,) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAm));

        // The rule: after any sequence ending with Collect, MinSum equals the value that was set (or 0 if never set)
        uint256 expectedMinSum = callSetMinSum ? initVal : 0;
        assertTrue(c.MinSum() == expectedMinSum);
    }
}

