        collectAmount = bound(collectAmount, 0, 1e18);

        // Set up: initialize, set MinSum to 0 so Collect can trigger
        c.SetLogFile(address(0));
        c.SetMinSum(0);
        c.Initialized();

        // Fund the contract via Put from different senders
        vm.deal(sender, depositAmount);
        vm.prank(sender);
        c.Put{value: depositAmount}(lockTime);

        // Record total ether balance of contract before Collect
        uint256 balanceBefore = address(c).balance;

        // Try Collect with the given amount
        vm.prank(sender);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, collectAmount));

        // After Collect, the sum of all Acc balances (only the sender's balance is stored) 
        // plus the contract balance must equal the total ether originally deposited (balanceBefore if no revert)
        // Since sender could have called Put multiple times, we track the actual balance
        // But a simpler invariant: after any Collect, the contract balance cannot exceed the sum of Acc balances
        // of all users, which is the total deposited ether. 
        // However, the mapping is not iterable, so we use a known invariant:
        // The contract balance must be <= sum of all Acc balances (which is impossible to read).
        // Alternative: After a successful Collect (non-revert), the contract balance should decrease by exactly collectAmount.

        // Change approach: use the revert boolean to assert that if Collect succeeds,
        // the sender's balance must have been at least collectAmount before the call.
        // We can read the sender's balance after the call to check consistency.

        // Actually use a simpler invariant: after Collect, the contract balance is never greater than before.
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter <= balanceBefore, "Contract balance should not increase after Collect");
    }
}
